class Resource extends Vector {
 heading='A field of almost-colors.';note='Drag the small anchors. Let the edges blend.';
 build(){const random=seedRandom(this.number('seed',17,1,100));const count=this.number('detail',6,3,12);this.anchors??=Array.from({length:12},()=>({x:90+random()*540,y:70+random()*280}));const id=this.artId;const colors=[this.color,'#d7bba0','#8a9eac','#a7a1c4','#c9bd8e','#9ba795'];return this.svg(`<defs><filter id="${id}-blur" x="-60%" y="-60%" width="220%" height="220%"><feGaussianBlur stdDeviation="30"/></filter><clipPath id="${id}-clip"><rect x="38" y="32" width="644" height="356" rx="135"/></clipPath></defs><rect x="38" y="32" width="644" height="356" rx="135" fill="#2b3835"/><g clip-path="url(#${id}-clip)" filter="url(#${id}-blur)">${this.anchors.slice(0,count).map((p,i)=>`<ellipse cx="${p.x}" cy="${p.y}" rx="${105+random()*80}" ry="${85+random()*70}" fill="${colors[i%colors.length]}" opacity=".92"/>`).join('')}</g><rect x="38" y="32" width="644" height="356" rx="135" fill="none" stroke="#e4e1d133"/>${this.anchors.slice(0,count).map((p,i)=>`<g data-handle="${i}" tabindex="0" role="button" aria-label="Color anchor ${i+1}"><circle cx="${p.x}" cy="${p.y}" r="16" fill="transparent"/><circle cx="${p.x}" cy="${p.y}" r="4" fill="#fff9" stroke="#25392f" stroke-width="1.5"/></g>`).join('')}`,'An editable field of blurred, overlapping color membranes. Drag or arrow-key each anchor.');}
 configured(name){if(name==='seed')this.anchors=null;super.configured(name);}
 interact(index,p){this.anchors[index]=p;this.draw();}
 keyHandle(index,key,shift){const p=this.anchors[index],step=shift?20:5;this.interact(index,{x:clamp(p.x+(key==='ArrowRight'?step:key==='ArrowLeft'?-step:0),30,690),y:clamp(p.y+(key==='ArrowDown'?step:key==='ArrowUp'?-step:0),30,390)});}
}
